//! {{APP_NAME}} — a Windows desktop app generated by AppHost.
//!
//! The library owns all non-GUI wiring so it can be tested without a
//! desktop: SettingsKit persistence, LogKit logging, CrashKit setup,
//! JobKit background work, ProcessKit child supervision, and an
//! UpdateKit check that is inert until a manifest URL is configured.
//! `src/main.rs` is only the Windows window/tray shell (plus a
//! headless self-check entry point on other platforms).

pub mod platform;
pub mod wiring;

pub use wiring::{AppContext, AppSettings, CrashStatus, DemoJob, UpdateCheck, CHILD_MARKER};

/// Package/binary slug substituted by AppHost's scaffold-app.py.
pub const APP_NAME: &str = "{{APP_NAME}}";
/// Stable application identity: single-instance mutex + data folder.
pub const APP_ID: &str = "{{APP_ID}}";
/// Generated application version.
pub const VERSION: &str = "{{VERSION}}";

/// Summary returned by the headless wiring self-check.
#[derive(Clone, Debug)]
pub struct SelfCheckReport {
    pub data_dir: String,
    pub launch_count: i64,
    pub job_percent: f64,
    pub child_stdout: String,
    pub update_outcome: String,
}

/// Run every non-GUI wiring path against a throwaway data directory.
///
/// This is what the non-Windows binary entry point runs. It uses the
/// real kits, then removes the temporary directory. On Windows the
/// GUI is the normal entry point; this function remains available to
/// tests and command-line diagnostics.
pub fn run_self_check() -> Result<SelfCheckReport, String> {
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|e| e.to_string())?
        .as_nanos();
    let root = std::env::temp_dir().join(format!(
        "{APP_ID}-self-check-{}-{stamp}",
        std::process::id()
    ));

    let result = (|| -> Result<SelfCheckReport, String> {
        let context = AppContext::start_at(&root, false)?;
        let job_status = context.run_demo_job()?;
        let child = context.run_demo_child()?;
        let update = context.check_for_updates();
        Ok(SelfCheckReport {
            data_dir: root.to_string_lossy().into_owned(),
            launch_count: context.settings().launch_count,
            job_percent: job_status.percent,
            child_stdout: child.stdout.trim().to_string(),
            update_outcome: update.summary(),
        })
        // `context` drops here, closing SettingsKit and LogKit before
        // the temporary directory is removed by the caller closure.
    })();

    let cleanup = std::fs::remove_dir_all(&root);
    match (result, cleanup) {
        (Ok(report), Ok(())) => Ok(report),
        (Ok(_), Err(e)) => Err(format!("self-check passed but cleanup failed: {e}")),
        (Err(e), _) => Err(e),
    }
}
